const item = $input.first().json;
let payload = {};

if (item.content) {
  try {
    payload = typeof item.content === 'string' ? JSON.parse(item.content) : item.content;
  } catch (err) {
    payload = {};
  }
} else {
  payload = item;
}

const routingKey = item.fields?.routingKey || payload.eventType || '';
const data = payload.data || {};
const leadId = data.leadId || payload.leadId || null;
const workflowRunId = data.workflowRunId || payload.workflowRunId || null;
const eventType = payload.eventType || routingKey || '';

return [{
  json: {
    eventId: payload.eventId || null,
    eventType,
    routingKey,
    data,
    leadId,
    workflowRunId,
    scoringContext: data.scoringContext || null,
    rawEvent: payload
  }
}];

const context = $input.first().json;
const parsedEvent = $('Parse Event Payload').first().json || {};
const lead = context.lead || {};
const qual = context.qualification || {};
const enrich = context.enrichment || {};
const interactions = context.interactions || [];
const features = context.scoringFeatures || {};

const prompt = `
You are an enterprise AI Lead Scoring model. Evaluate the following prospective lead:

Contact Details:
- Name: ${lead.firstName} ${lead.lastName || ''}
- Email: ${lead.email}
- Job Title: ${enrich.contactJobTitle || lead.jobTitle || 'Unknown'}
- Company: ${enrich.companyName || lead.companyName || 'Unknown'}
- Website: ${enrich.companyWebsite || lead.companyWebsite || 'None'}
- Industry: ${enrich.companyIndustry || lead.industry || 'Unknown'}
- Company Size: ${enrich.companySize ?? lead.companySize ?? 'Unknown'}

Latest Qualification:
- Status: ${qual.status || 'NOT_QUALIFIED'}
- Confidence: ${qual.confidence || 'N/A'}
- Intent: ${qual.intent || 'N/A'}
- Reason: ${qual.reason || 'N/A'}

Interaction History:
- Total Touchpoints: ${interactions.length}
- Recent Touchpoints (30 days): ${features.recentInteractionsCount || 0}

Scoring Rules (0 - 100):
- HOT (>= 70): High commercial intent, verified decision maker (VP/C-Level/Director), mid-market to enterprise size (>= 50 employees), active touchpoints.
- WARM (40 - 69): Moderate fit or pending qualification, small-to-mid business, standard interactions.
- COLD (< 40): Low intent, disqualified, missing key contact info, or inactive.
`;

return [{
  json: {
    leadId: lead.id,
    workflowRunId: parsedEvent.workflowRunId || null,
    prompt,
    context
  }
}];

const item = $input.first().json;
const context = item.context || {};
const lead = context.lead || {};
const qual = context.qualification || null;
const enrich = context.enrichment || null;
const interactions = context.interactions || [];
const f = context.scoringFeatures || {};

// Multi-factor AI Scoring Engine
let score = 25; // baseline
const breakdown = {
  baseline: 25,
  decisionMakerPoints: 0,
  companyFitPoints: 0,
  websitePoints: 0,
  qualificationPoints: 0,
  engagementPoints: 0
};

// 1. Decision maker factor (up to 20 pts)
if (f.isDecisionMaker) {
  breakdown.decisionMakerPoints = 20;
  score += 20;
}

// 2. Firmographic size fit (up to 15 pts)
const size = f.companySize;
if (typeof size === 'number') {
  if (size >= 100) {
    breakdown.companyFitPoints = 15;
    score += 15;
  } else if (size >= 20) {
    breakdown.companyFitPoints = 10;
    score += 10;
  } else if (size >= 5) {
    breakdown.companyFitPoints = 5;
    score += 5;
  }
}

// 3. Digital presence factor (up to 10 pts)
if (f.hasWebsite) {
  breakdown.websitePoints = 10;
  score += 10;
}

// 4. AI Qualification adjustment (up to 25 pts)
if (qual && qual.status === 'QUALIFIED') {
  const conf = typeof qual.confidence === 'number' ? qual.confidence : 0.8;
  const qualBonus = Math.round(conf * 25);
  breakdown.qualificationPoints = qualBonus;
  score += qualBonus;
} else if (qual && qual.status === 'DISQUALIFIED') {
  breakdown.qualificationPoints = -20;
  score -= 20;
} else if (qual && qual.status === 'NEEDS_REVIEW') {
  breakdown.qualificationPoints = 5;
  score += 5;
}

// 5. Engagement & Touchpoint activity (up to 20 pts)
const recentCount = f.recentInteractionsCount || interactions.length || 0;
const engagementBonus = Math.min(20, recentCount * 5);
breakdown.engagementPoints = engagementBonus;
score += engagementBonus;

// Clamp score between 0 and 100
const finalScore = Math.max(0, Math.min(100, Math.round(score)));

// Label assignment according to business rule
let label = 'COLD';
if (finalScore >= 70) {
  label = 'HOT';
} else if (finalScore >= 40) {
  label = 'WARM';
}

// Explanation synthesis
const drivers = [];
if (breakdown.qualificationPoints > 15) drivers.push('Strong qualified intent');
if (breakdown.decisionMakerPoints > 0) drivers.push('Executive decision-maker title');
if (breakdown.companyFitPoints >= 10) drivers.push(`Target company scale (${size} employees)`);
if (breakdown.engagementPoints >= 10) drivers.push(`Active engagement (${recentCount} touchpoints)`);
if (qual && qual.status === 'DISQUALIFIED') drivers.push('Disqualified in previous screening');
if (drivers.length === 0) drivers.push('Standard inbound lead profile');

const reason = `[${label}] Score ${finalScore}/100: ${drivers.join(', ')}.`;

return [{
  json: {
    leadId: item.leadId,
    workflowRunId: item.workflowRunId,
    score: finalScore,
    label,
    reason,
    scoringFeatures: {
      ...f,
      breakdown
    },
    modelProvider: 'crm-ai-scoring-engine',
    modelName: 'lead-evaluator-v2',
    modelVersion: '2.0.0',
    inputSnapshot: {
      lead: { id: lead.id, email: lead.email, company: lead.companyName, jobTitle: lead.jobTitle },
      qualification: qual ? { status: qual.status, confidence: qual.confidence } : null,
      enrichment: enrich ? { companySize: enrich.companySize, companyWebsite: enrich.companyWebsite } : null,
      interactionsCount: interactions.length
    },
    outputSnapshot: {
      score: finalScore,
      label,
      breakdown,
      reason
    }
  }
}];

const item = $input.first().json;

// Validate score
let score = Number(item.score);
if (isNaN(score)) {
  score = 50;
}
score = Math.max(0, Math.min(100, Math.round(score * 100) / 100));

// Enforce label rules:
// HOT >= 70, WARM 40-69, COLD < 40
let label = 'COLD';
if (score >= 70) {
  label = 'HOT';
} else if (score >= 40) {
  label = 'WARM';
}

return [{
  json: {
    leadId: item.leadId,
    workflowRunId: item.workflowRunId || null,
    score,
    label,
    reason: item.reason || `AI evaluated score: ${score}`,
    modelProvider: item.modelProvider || 'crm-ai-scoring-engine',
    modelName: item.modelName || 'lead-evaluator-v2',
    modelVersion: item.modelVersion || '2.0.0',
    scoringFeatures: item.scoringFeatures || {},
    inputSnapshot: item.inputSnapshot || {},
    outputSnapshot: item.outputSnapshot || {}
  }
}];
